<script>
document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('[data-password-toggle]').forEach(function(button){button.addEventListener('click',function(){var input=document.getElementById(button.dataset.passwordToggle);if(!input)return;var show=input.type==='password';input.type=show?'text':'password';var eye=button.querySelector('[data-eye]');var eyeOff=button.querySelector('[data-eye-off]');if(eye)eye.style.display=show?'none':'';if(eyeOff)eyeOff.style.display=show?'':'none';button.setAttribute('aria-label',show?'Hide password':'Show password')})})});
</script>

